def verifier(assign):
    # Recompute per the construction logic and validate constraints. Then return the minimal area and True/False.
    try:
        a = int(assign['a']); b = int(assign['b']); p = int(assign['p']); q = int(assign['q']); parallel_leg = int(assign['parallel_leg'])
    except Exception:
        # Missing or invalid fields
        return (False, None)
    if not (1 <= a < b and 2 <= p and 2 <= q):
        # domain sanity
        return (False, None)
    # Compute candidate options exactly as in generator
    options = []
    # Option A: p equals a-leg in U2 -> k = p/a, require k*b < q, t = (q - k*b)/q if we cut parallel to b in T
    kA = Fraction(p, a)
    if kA * b < q:
        t_b = Fraction(q - kA*b, q)
        if 0 < t_b < 1:
            area = t_b*t_b*Fraction(a*b, 2)
            options.append((area, 'b'))
    # Option B: q equals a-leg in U2 -> k = q/a, require k*b < p; t = (p - k*b)/p if cut parallel to b
    kB = Fraction(q, a)
    if kB * b < p:
        t_b2 = Fraction(p - kB*b, p)
        if 0 < t_b2 < 1:
            area = t_b2*t_b2*Fraction(a*b, 2)
            options.append((area, 'b'))
    # Option C: p equals b-leg in U2 -> k = p/b, require k*a < q; t = (q - k*a)/q if cut parallel to a
    kC = Fraction(p, b)
    if kC * a < q:
        t_a = Fraction(q - kC*a, q)
        if 0 < t_a < 1:
            area = t_a*t_a*Fraction(a*b, 2)
            options.append((area, 'a'))
    # Option D: q equals b-leg in U2 -> k = q/b, require k*a < p; t = (p - k*a)/p if cut parallel to a
    kD = Fraction(q, b)
    if kD * a < p:
        t_a2 = Fraction(p - kD*a, p)
        if 0 < t_a2 < 1:
            area = t_a2*t_a2*Fraction(a*b, 2)
            options.append((area, 'a'))
    if not options:
        # No valid configuration exists under the interpretation; reject instance.
        return (False, None)
    # Among options, the problem statement commits to the chosen parallel_leg (either a or b). We must ensure that at least one valid option matches that.
    # Compute the minimum area across those options that match the specified parallel_leg; if none, then invalid.
    target = 'a' if parallel_leg == a else ('b' if parallel_leg == b else None)
    if target is None:
        return (False, None)
    filtered = [area for (area, which) in options if which == target]
    if not filtered:
        # The specified parallel_leg choice is not feasible.
        return (False, None)
    area_min = min(filtered)
    # Return m+n of reduced fraction area_min
    area_min = area_min.limit_denominator()
    m = area_min.numerator
    n = area_min.denominator
    return (True, m + n)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

